// @lib comum/lib/supabase.mjs
// Chamadas ao Supabase (PostgREST) e despacho da fila "Sincronizar agora" — funções puras, sem import.
// Usada nos nós Code dos workflows (cópia marcada com `// @lib comum/lib/supabase.mjs`, conferida por `npm run n8n:verificar`).
// O transporte HTTP é injetado (`http(req) → Promise<{status, headers, corpo}>`): no N8N vem de `criarHttpN8n(this.helpers)`,
// nos testes de `criarHttpFetch(fetch)`.

const NOMES_WORKFLOWS = {
  CONTROLID_USUARIOS: 'MDG · Control iD · Importar usuários',
  CONTROLID_BATIDAS: 'MDG · Control iD · Importar batidas',
  CONTROLID_EXPORTAR: 'MDG · Control iD · Exportar funcionários',
  ZIG_IMPORTAR: 'MDG · Zig · Importar',
  EXPORTAR_FECHAMENTO: 'MDG · Exportar fechamento CSV',
  SINCRONIZAR_AGORA: 'MDG · Sincronizar agora (fila)',
  AGENDADOR: 'MDG · Agendador',
  ROTINA_DIARIA: 'MDG · Rotina diária',
  ERROS: 'MDG · Tratador de erros',
}

/** Variável de ambiente que guarda o id (no N8N) de cada subfluxo. */
const VARIAVEIS_SUBFLUXOS = {
  CONTROLID_USUARIOS: 'MDG_WF_CONTROLID_USUARIOS',
  CONTROLID_BATIDAS: 'MDG_WF_CONTROLID_BATIDAS',
  CONTROLID_EXPORTAR: 'MDG_WF_CONTROLID_EXPORTAR',
  ZIG_IMPORTAR: 'MDG_WF_ZIG_IMPORTAR',
  EXPORTAR_FECHAMENTO: 'MDG_WF_EXPORTAR_FECHAMENTO',
}

/** Tipo de `sync_execucoes` aberto por cada workflow (usado pelo tratador de erros). */
const TIPO_EXECUCAO_POR_WORKFLOW = {
  'MDG · Control iD · Importar usuários': 'controlid_usuarios',
  'MDG · Control iD · Importar batidas': 'controlid_batidas',
  'MDG · Control iD · Exportar funcionários': 'controlid_exportar_usuarios',
  'MDG · Zig · Importar': 'zig_importar',
  'MDG · Exportar fechamento CSV': 'exportar_fechamento',
  'MDG · Rotina diária': 'apurar_ponto',
}

/**
 * Lê uma variável tentando cada fonte em ordem (ex.: `[() => $env, () => $vars]`). Fonte que lança erro
 * (ex.: `$env` bloqueado no N8N Cloud) é pulada. Valor vazio conta como ausente.
 */
function lerVariavel(nome, fontes, padrao) {
  for (const fonte of fontes || []) {
    try {
      const obj = typeof fonte === 'function' ? fonte() : fonte
      const v = obj ? obj[nome] : undefined
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim()
    } catch (e) {
      // fonte indisponível — tenta a próxima
    }
  }
  return padrao
}

/** Configuração do Supabase a partir das variáveis. Lança erro claro se faltar algo. */
function configSupabase(fontes) {
  const url = lerVariavel('SUPABASE_URL', fontes)
  const chave = lerVariavel('SUPABASE_SERVICE_ROLE_KEY', fontes)
  if (!url) throw new Error('Variável SUPABASE_URL não configurada no N8N')
  if (!chave) throw new Error('Variável SUPABASE_SERVICE_ROLE_KEY não configurada no N8N')
  return { url: url.replace(/\/+$/, ''), chave }
}

function cabecalhosSupabase(chave) {
  return { apikey: chave, Authorization: `Bearer ${chave}`, 'Content-Type': 'application/json', Accept: 'application/json' }
}

/** Monta a requisição `POST {url}/rest/v1/rpc/<nome>` com o corpo `{p_...}` (§12.2). */
function montarChamadaRpc(cfg, nome, args, timeoutMs) {
  if (!/^[a-z_][a-z0-9_]*$/.test(nome || '')) throw new Error(`Nome de RPC inválido: ${nome}`)
  const corpo = {}
  for (const [k, v] of Object.entries(args || {})) if (v !== undefined) corpo[k] = v
  return {
    method: 'POST',
    url: `${cfg.url}/rest/v1/rpc/${nome}`,
    headers: cabecalhosSupabase(cfg.chave),
    corpo,
    timeoutMs: timeoutMs || 60000,
  }
}

/** 408, 425, 429 e 5xx valem nova tentativa; demais 4xx não. `null` (falha de rede/timeout) também vale. */
function deveRetentar(status) {
  if (status === null || status === undefined) return true
  return status === 408 || status === 425 || status === 429 || status >= 500
}

/** Lê `Retry-After` (segundos ou data HTTP) em ms; null se ausente/inválido. */
function lerRetryAfter(headers, agoraMs) {
  if (!headers) return null
  let v = headers['retry-after'] ?? headers['Retry-After']
  if (v === undefined || v === null || v === '') return null
  v = String(v).trim()
  if (/^\d+(\.\d+)?$/.test(v)) return Math.round(Number(v) * 1000)
  const data = Date.parse(v)
  if (Number.isNaN(data)) return null
  return Math.max(0, data - (agoraMs ?? Date.now()))
}

/** Espera antes da tentativa `n+1` (n = tentativas já feitas, ≥ 1): base × 2^(n−1), respeitando Retry-After, limitado. */
function esperaAntesDaProxima(n, opcoes) {
  const base = opcoes?.esperaMs ?? 5000
  const max = opcoes?.maxEsperaMs ?? 60000
  const exponencial = base * Math.pow(2, Math.max(0, n - 1))
  const pedido = opcoes?.retryAfterMs
  return Math.min(max, Math.max(exponencial, pedido ?? 0))
}

class ErroHttp extends Error {
  constructor(mensagem, detalhes) {
    super(mensagem)
    this.name = 'ErroHttp'
    this.status = detalhes?.status ?? null
    this.corpo = detalhes?.corpo
    this.tentativas = detalhes?.tentativas ?? 1
    this.url = detalhes?.url
  }
}

/** Remove segredos de uma URL antes de aparecer em mensagem de erro. */
function urlSegura(url) {
  return String(url || '').replace(/([?&](session|token|apikey|key)=)[^&]*/gi, '$1***')
}

function resumoCorpo(corpo) {
  if (corpo === undefined || corpo === null || corpo === '') return ''
  if (typeof corpo === 'string') return corpo.slice(0, 300)
  if (typeof corpo === 'object') {
    const m = corpo.message || corpo.mensagem || corpo.error || corpo.erro || corpo.hint
    if (m) return String(m).slice(0, 300)
    try { return JSON.stringify(corpo).slice(0, 300) } catch (e) { return '' }
  }
  return String(corpo).slice(0, 300)
}

/**
 * Executa `req` com retentativa e *backoff* exponencial em falha de rede, timeout, 408/425/429/5xx.
 * opcoes: { tentativas = 3, esperaMs = 5000, maxEsperaMs = 60000, dormir(ms), rotulo }
 * Retorna `{ status, headers, corpo, tentativas }` (2xx). Lança `ErroHttp` (com `.tentativas`) se esgotar ou se 4xx.
 */
async function requisitarComRetentativa(http, req, opcoes) {
  const tentativas = Math.max(1, opcoes?.tentativas ?? 3)
  const dormir = opcoes?.dormir || ((ms) => new Promise((ok) => setTimeout(ok, ms)))
  const rotulo = opcoes?.rotulo || `${req.method} ${urlSegura(req.url).split('?')[0]}`
  let ultimo = null
  for (let n = 1; n <= tentativas; n++) {
    let resposta = null
    let erroRede = null
    try {
      resposta = await http(req)
    } catch (e) {
      erroRede = e
    }
    if (resposta && resposta.status >= 200 && resposta.status < 300) return { ...resposta, tentativas: n }
    const status = resposta ? resposta.status : null
    ultimo = new ErroHttp(
      resposta
        ? `${rotulo}: HTTP ${status}${resumoCorpo(resposta.corpo) ? ' — ' + resumoCorpo(resposta.corpo) : ''}`
        : `${rotulo}: ${erroRede && erroRede.message ? erroRede.message : 'falha de rede'}`,
      { status, corpo: resposta ? resposta.corpo : undefined, tentativas: n, url: urlSegura(req.url) },
    )
    if (!deveRetentar(status) || n === tentativas) break
    await dormir(esperaAntesDaProxima(n, { esperaMs: opcoes?.esperaMs, maxEsperaMs: opcoes?.maxEsperaMs, retryAfterMs: resposta ? lerRetryAfter(resposta.headers) : null }))
  }
  if (tentativas > 1 && ultimo.tentativas > 1) ultimo.message += ` (após ${ultimo.tentativas} tentativas)`
  throw ultimo
}

/** Chama uma RPC (3 tentativas, 5 s de base — §12.2) e devolve o corpo já interpretado. */
async function chamarRpc(http, cfg, nome, args, opcoes) {
  const req = montarChamadaRpc(cfg, nome, args, opcoes?.timeoutMs)
  const r = await requisitarComRetentativa(http, req, { tentativas: 3, esperaMs: 5000, rotulo: `RPC ${nome}`, ...(opcoes || {}) })
  return r.corpo === '' ? null : r.corpo
}

/** Lê linhas de uma tabela via PostgREST (service_role). `filtros` já no formato do PostgREST (ex.: {status: 'eq.executando'}). */
async function selecionar(http, cfg, tabela, filtros, opcoes) {
  const qs = Object.entries(filtros || {}).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&')
  const req = { method: 'GET', url: `${cfg.url}/rest/v1/${tabela}${qs ? '?' + qs : ''}`, headers: cabecalhosSupabase(cfg.chave), timeoutMs: 30000 }
  const r = await requisitarComRetentativa(http, req, { tentativas: 3, esperaMs: 5000, rotulo: `GET ${tabela}`, ...(opcoes || {}) })
  return Array.isArray(r.corpo) ? r.corpo : []
}

function mensagemDeErro(e) {
  if (!e) return 'Erro desconhecido'
  if (typeof e === 'string') return e.slice(0, 1000)
  const m = e.message || e.description || e.erro || (e.error && (e.error.message || e.error)) || String(e)
  return String(m).slice(0, 1000)
}

/** Adaptador para `this.helpers.httpRequest` do nó Code do N8N. */
function criarHttpN8n(helpers) {
  return async (req) => {
    const r = await helpers.httpRequest({
      method: req.method,
      url: req.url,
      headers: req.headers,
      body: req.corpo,
      json: req.texto ? false : true,
      timeout: req.timeoutMs || 60000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    })
    let corpo = r.body
    if (!req.texto && typeof corpo === 'string' && corpo !== '') {
      try { corpo = JSON.parse(corpo) } catch (e) { /* mantém texto */ }
    }
    return { status: r.statusCode, headers: r.headers || {}, corpo }
  }
}

/** Adaptador para `fetch` (Node ≥ 18) — testes e uso local. */
function criarHttpFetch(fetchFn) {
  return async (req) => {
    const controle = new AbortController()
    const t = setTimeout(() => controle.abort(), req.timeoutMs || 60000)
    try {
      const r = await fetchFn(req.url, {
        method: req.method,
        headers: req.headers,
        body: req.corpo === undefined ? undefined : typeof req.corpo === 'string' ? req.corpo : JSON.stringify(req.corpo),
        signal: controle.signal,
      })
      const texto = await r.text()
      let corpo = texto
      if (!req.texto && texto !== '') {
        try { corpo = JSON.parse(texto) } catch (e) { /* mantém texto */ }
      }
      const headers = {}
      r.headers.forEach((v, k) => { headers[k.toLowerCase()] = v })
      return { status: r.status, headers, corpo }
    } catch (e) {
      if (e && e.name === 'AbortError') throw new Error(`tempo esgotado (${req.timeoutMs || 60000} ms)`)
      throw e
    } finally {
      clearTimeout(t)
    }
  }
}

// ----------------------------------------------------------------------------------------------- despacho (§12.3)

/** Subfluxos (em ordem) de uma combinação tipo × escopo. `envioAtivo` = parametros.envio.ativo do equipamento (adendo A.5). */
function subfluxosDe(tipo, escopo, envioAtivo) {
  const controlid = tipo === 'controlid_acesso' || tipo === 'controlid_rep'
  if (escopo === 'exportar_fechamento') return ['EXPORTAR_FECHAMENTO']
  if (tipo === 'zig') return escopo === 'tudo' || escopo === 'vendas' ? ['ZIG_IMPORTAR'] : null
  if (controlid) {
    if (escopo === 'tudo') return envioAtivo ? ['CONTROLID_USUARIOS', 'CONTROLID_EXPORTAR', 'CONTROLID_BATIDAS'] : ['CONTROLID_USUARIOS', 'CONTROLID_BATIDAS']
    if (escopo === 'funcionarios') return ['CONTROLID_USUARIOS']
    if (escopo === 'batidas') return ['CONTROLID_BATIDAS']
    if (escopo === 'exportar_funcionarios') return ['CONTROLID_EXPORTAR']
  }
  return null
}

/** Item de entrada de todo subfluxo (§12.3). */
function entradaSubfluxo(s, gatilho) {
  return {
    integracao_id: s.integracao_id ?? null,
    empresa_id: s.empresa_id ?? null,
    tipo: s.integracao_tipo ?? s.tipo ?? null,
    escopo: s.escopo ?? 'tudo',
    gatilho: gatilho || (s.solicitacao_id ? 'manual' : 'agendado'),
    solicitacao_id: s.solicitacao_id ?? null,
    data_inicio: s.data_inicio ?? null,
    data_fim: s.data_fim ?? null,
    parametros: s.parametros && typeof s.parametros === 'object' ? s.parametros : {},
  }
}

/**
 * Expande uma solicitação da fila (linha de `ingestao_sync_pegar_solicitacoes`) — ou uma integração vencida do agendador —
 * em passos ordenados. Cada passo é um item: os campos da entrada do subfluxo no topo + `_despacho` com o controle.
 * `ids` = { ZIG_IMPORTAR: '<id do workflow>', ... }. `envioAtivo` só importa para Control iD com escopo `tudo`.
 */
function planejarDespacho(s, ids, opcoes) {
  const gatilho = opcoes?.gatilho
  const entrada = entradaSubfluxo(s, gatilho)
  const chave = s.solicitacao_id || `${entrada.integracao_id}|${entrada.escopo}`
  const base = (ordem, total, extra) => ({ ...entrada, _despacho: { chave, solicitacao_id: entrada.solicitacao_id, ordem, total, ...extra } })
  if (entrada.escopo === 'apurar_ponto') return [base(1, 1, { acao: 'apurar_ponto' })]
  if (entrada.escopo === 'exportar_fechamento' && !(entrada.parametros && entrada.parametros.fechamento_id)) {
    return [base(1, 1, { acao: 'invalido', erro: 'Solicitação de exportação sem fechamento_id' })]
  }
  const lista = subfluxosDe(entrada.tipo, entrada.escopo, opcoes?.envioAtivo === true)
  if (!lista) return [base(1, 1, { acao: 'invalido', erro: `Escopo "${entrada.escopo}" não se aplica a integração do tipo "${entrada.tipo}"` })]
  // Falta o id de algum subfluxo → a solicitação inteira vira um único passo inválido (nada roda pela metade).
  const faltando = lista.find((nome) => !(ids && ids[nome]))
  if (faltando) {
    return [base(1, 1, { acao: 'invalido', subfluxo: faltando, workflow_nome: NOMES_WORKFLOWS[faltando], tipo_execucao: TIPO_EXECUCAO_POR_WORKFLOW[NOMES_WORKFLOWS[faltando]],
      erro: `Variável ${VARIAVEIS_SUBFLUXOS[faltando]} não configurada no N8N (id do workflow "${NOMES_WORKFLOWS[faltando]}")` })]
  }
  return lista.map((nome, i) => base(i + 1, lista.length, { acao: 'subfluxo', subfluxo: nome, workflow_id: String(ids[nome]), workflow_nome: NOMES_WORKFLOWS[nome] }))
}

/** `parametros.envio.ativo` de uma configuração de integração (adendo de envio ao Control iD). */
function envioAtivo(config) {
  return !!(config && config.parametros && config.parametros.envio && config.parametros.envio.ativo === true)
}

/** Precisa ler a configuração da integração para despachar? (só Control iD com escopo `tudo`, por causa do envio). */
function precisaConfigParaDespacho(s) {
  const tipo = s.integracao_tipo ?? s.tipo
  return (tipo === 'controlid_acesso' || tipo === 'controlid_rep') && (s.escopo ?? 'tudo') === 'tudo' && !!s.integracao_id
}

/** Ids dos subfluxos a partir das variáveis. */
function idsSubfluxos(fontes) {
  const ids = {}
  for (const [nome, variavel] of Object.entries(VARIAVEIS_SUBFLUXOS)) ids[nome] = lerVariavel(variavel, fontes)
  return ids
}

/** Normaliza a saída de um subfluxo (ou o erro do nó Execute Workflow) para `{status, lidos, gravados, ignorados, erro, execucao_ids}`. */
function normalizarSaida(json) {
  const j = json || {}
  if (j.error) {
    const erro = typeof j.error === 'string' ? j.error : mensagemDeErro(j.error)
    return { status: 'erro', lidos: 0, gravados: 0, ignorados: 0, erro, execucao_ids: [] }
  }
  const status = ['sucesso', 'parcial', 'erro'].includes(j.status) ? j.status : 'erro'
  return {
    status,
    lidos: Number(j.lidos) || 0,
    gravados: Number(j.gravados) || 0,
    ignorados: Number(j.ignorados) || 0,
    erro: j.erro ?? (j.status ? null : 'Subfluxo não devolveu status'),
    execucao_ids: Array.isArray(j.execucao_ids) ? j.execucao_ids.filter(Boolean) : j.execucao_id ? [j.execucao_id] : [],
  }
}

/**
 * Junta os resultados dos passos de cada solicitação → `[{solicitacao_id, status: 'concluida'|'erro', mensagem, execucao_id}]`.
 * `passos` = [{ _despacho, resultado: saída normalizada }]. Qualquer passo `erro` → solicitação `erro`.
 */
function consolidarSolicitacoes(passos) {
  const grupos = new Map()
  for (const p of passos) {
    const d = p._despacho || {}
    if (!d.solicitacao_id) continue
    if (!grupos.has(d.solicitacao_id)) grupos.set(d.solicitacao_id, [])
    grupos.get(d.solicitacao_id).push(p)
  }
  const saida = []
  for (const [solicitacao_id, lista] of grupos) {
    lista.sort((a, b) => (a._despacho.ordem || 0) - (b._despacho.ordem || 0))
    const resultados = lista.map((p) => p.resultado || { status: 'erro', erro: 'Sem resultado' })
    const erros = lista.filter((p, i) => resultados[i].status === 'erro')
    const parciais = resultados.filter((r) => r.status === 'parcial').length
    const tot = resultados.reduce((a, r) => ({ lidos: a.lidos + (r.lidos || 0), gravados: a.gravados + (r.gravados || 0), ignorados: a.ignorados + (r.ignorados || 0) }), { lidos: 0, gravados: 0, ignorados: 0 })
    const ids = resultados.flatMap((r) => r.execucao_ids || [])
    let mensagem
    if (erros.length) {
      mensagem = erros.map((p) => `${p._despacho.workflow_nome || p._despacho.subfluxo || p._despacho.acao}: ${p.resultado?.erro || p._despacho.erro || 'erro'}`).join(' | ')
    } else {
      mensagem = `${tot.lidos} lidos, ${tot.gravados} gravados, ${tot.ignorados} ignorados${parciais ? ` (${parciais} parcial)` : ''}`
    }
    saida.push({ solicitacao_id, status: erros.length ? 'erro' : 'concluida', mensagem: mensagem.slice(0, 1000), execucao_id: ids[ids.length - 1] || null })
  }
  return saida
}

// ----------------------------------------------------------------------------------------------- sync_execucoes

/**
 * Abre uma `sync_execucoes`, roda `trabalho(execucaoId)` e fecha com o resultado. `trabalho` devolve
 * `{status?, lidos, gravados, ignorados, detalhes?, tentativas?, erro?}`; exceção → fecha com `erro` e devolve a saída de erro.
 * Saída no formato do §12.3: `{execucao_ids, status, lidos, gravados, ignorados, erro}` (+ `retorno` do trabalho).
 */
async function comExecucao(http, cfg, abertura, trabalho) {
  const execucaoId = await chamarRpc(http, cfg, 'ingestao_sync_iniciar', {
    p_tipo: abertura.tipo,
    p_gatilho: abertura.gatilho === 'manual' || abertura.gatilho === 'webhook' ? abertura.gatilho : 'agendado',
    p_workflow: abertura.workflow,
    p_empresa: abertura.empresa_id ?? null,
    p_integracao: abertura.integracao_id ?? null,
    p_solicitacao: abertura.solicitacao_id ?? null,
    p_periodo_inicio: abertura.periodo_inicio ?? null,
    p_periodo_fim: abertura.periodo_fim ?? null,
    p_n8n_execution_id: abertura.n8n_execution_id != null ? String(abertura.n8n_execution_id) : null,
  })
  let r
  try {
    r = (await trabalho(execucaoId)) || {}
  } catch (e) {
    r = { status: 'erro', erro: mensagemDeErro(e), tentativas: e && e.tentativas ? e.tentativas : 1 }
  }
  const status = ['sucesso', 'parcial', 'erro'].includes(r.status) ? r.status : 'sucesso'
  const saida = {
    execucao_ids: [execucaoId],
    status,
    lidos: Number(r.lidos) || 0,
    gravados: Number(r.gravados) || 0,
    ignorados: Number(r.ignorados) || 0,
    erro: status === 'sucesso' ? null : r.erro || null,
  }
  await chamarRpc(http, cfg, 'ingestao_sync_finalizar', {
    p_execucao: execucaoId,
    p_status: status,
    p_lidos: saida.lidos,
    p_gravados: saida.gravados,
    p_ignorados: saida.ignorados,
    p_erro: saida.erro,
    p_detalhes: r.detalhes || {},
    p_tentativas: Math.max(1, Number(r.tentativas) || 1),
  })
  if (r.retorno !== undefined) saida.retorno = r.retorno
  return saida
}

// @lib zig/lib/zig.mjs
// Importação da Zig (contrato §8, §11.5, §12.5) — funções puras, sem import.
// Copiada no nó Code do workflow "MDG · Zig · Importar" com `// @lib zig/lib/zig.mjs` (conferida por `npm run n8n:verificar`).
// A importação recebe as dependências por parâmetro: `requisitar(req, opcoes)` (HTTP com retentativa — comum/lib/supabase.mjs)
// e `rpc(nome, args)` (chamada ao Supabase), o que a deixa testável fora do N8N.

const ZIG_BASE_PADRAO = 'https://api.zigcore.com.br/integration'
const ZIG_MAX_DIAS = 31
const ZIG_PAUSA_MS = 300

/** Endpoints importados por loja × dia, na ordem de chamada, com a RPC de ingestão de cada um (§11.5). */
const ENDPOINTS_ZIG = [
  { chave: 'saida_produtos', caminho: '/erp/saida-produtos', rpc: 'ingestao_zig_saida_produtos' },
  { chave: 'faturamento', caminho: '/erp/faturamento', rpc: 'ingestao_zig_faturamento' },
  { chave: 'compradores', caminho: '/erp/compradores', rpc: 'ingestao_zig_compradores' },
  { chave: 'faturamento_bandeiras', caminho: '/erp/faturamento/detalhesMaquinaIntegrada', rpc: 'ingestao_zig_faturamento_bandeiras' },
]

const RE_DATA = /^\d{4}-\d{2}-\d{2}$/

function dataValida(iso) {
  if (typeof iso !== 'string' || !RE_DATA.test(iso)) return false
  const d = new Date(iso + 'T00:00:00Z')
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === iso
}

function somarDias(iso, n) {
  const d = new Date(Date.parse(iso + 'T00:00:00Z') + n * 86400000)
  return d.toISOString().slice(0, 10)
}

/** Dias (AAAA-MM-DD) de `inicio` a `fim`, inclusive. Lança erro se inválido ou maior que `max`. */
function diasDoPeriodo(inicio, fim, max) {
  if (!dataValida(inicio) || !dataValida(fim)) throw new Error(`Período inválido: ${inicio} a ${fim}`)
  if (fim < inicio) throw new Error(`Período inválido: ${inicio} a ${fim}`)
  const limite = max ?? ZIG_MAX_DIAS
  const dias = []
  for (let d = inicio; d <= fim; d = somarDias(d, 1)) {
    dias.push(d)
    if (dias.length > limite) throw new Error(`Período máximo de ${limite} dias`)
  }
  return dias
}

/**
 * Período a importar (§12.5): padrão `[dia_trabalho_atual − dias_retroativos, dia_trabalho_atual]`.
 * Sincronização manual com `data_inicio`/`data_fim` usa as datas pedidas (ignora `dias_retroativos`).
 * `fim` nunca passa do dia de trabalho atual; períodos com mais de 31 dias ficam com os 31 últimos (`truncado = true`).
 */
function periodoZig(entrada, config, max) {
  const limite = max ?? ZIG_MAX_DIAS
  const hoje = config && config.dia_trabalho_atual
  if (!dataValida(hoje)) throw new Error('Configuração sem dia_trabalho_atual')
  const retro = Math.max(0, Math.min(limite - 1, Number(config.parametros && config.parametros.dias_retroativos != null ? config.parametros.dias_retroativos : 2) || 0))
  let fim = entrada && entrada.data_fim ? entrada.data_fim : hoje
  let inicio = entrada && entrada.data_inicio ? entrada.data_inicio : null
  if (!dataValida(fim)) throw new Error(`Data final inválida: ${fim}`)
  if (fim > hoje) fim = hoje
  if (inicio === null) inicio = somarDias(fim, -retro)
  if (!dataValida(inicio)) throw new Error(`Data inicial inválida: ${inicio}`)
  if (inicio > fim) throw new Error(`Período inválido: ${inicio} a ${fim}`)
  let truncado = false
  if (somarDias(inicio, limite - 1) < fim) {
    inicio = somarDias(fim, -(limite - 1))
    truncado = true
  }
  return { inicio, fim, dias: diasDoPeriodo(inicio, fim, limite), truncado }
}

/** URL completa de um endpoint da Zig. */
function urlZig(base, caminho, params) {
  const raiz = String(base || ZIG_BASE_PADRAO).replace(/\/+$/, '')
  const qs = Object.entries(params || {})
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join('&')
  return `${raiz}${caminho}${qs ? '?' + qs : ''}`
}

/** Requisição GET da Zig: cabeçalho `Authorization: {token}` (sem "Bearer"). */
function requisicaoZig(base, token, caminho, params, timeoutMs) {
  return { method: 'GET', url: urlZig(base, caminho, params), headers: { Authorization: token, Accept: 'application/json' }, timeoutMs: timeoutMs || 60000 }
}

/** Parâmetros de um dia para uma loja (um dia por vez: dtinicio = dtfim). */
function paramsDia(loja, dia) {
  return { dtinicio: dia, dtfim: dia, loja }
}

/**
 * Lojas a importar: as devolvidas pela API (`[{id, name}]`), menos as marcadas `sincronizar = false` em `config.lojas`.
 * Lojas novas (ainda não em `zig_lojas`) entram (a ingestão cria com `sincronizar = true`).
 */
function lojasParaSincronizar(lojasApi, lojasConfig) {
  const desligadas = new Set((lojasConfig || []).filter((l) => l && l.sincronizar === false).map((l) => String(l.loja_id_externo)))
  const vistas = new Set()
  const saida = []
  for (const l of lojasApi || []) {
    if (!l || l.id === undefined || l.id === null) continue
    const id = String(l.id)
    if (desligadas.has(id) || vistas.has(id)) continue
    vistas.add(id)
    saida.push(id)
  }
  return saida
}

/** Plano de chamadas (loja × dia × endpoint), na ordem em que serão feitas. */
function planejarChamadas(lojas, dias) {
  const plano = []
  for (const loja of lojas) for (const dia of dias) for (const e of ENDPOINTS_ZIG) plano.push({ loja, dia, endpoint: e.chave, caminho: e.caminho, rpc: e.rpc })
  return plano
}

/** Converte a resposta da Zig no array repassado à RPC (a ingestão recebe o JSON da API sem transformar). */
function itensDaResposta(corpo) {
  if (Array.isArray(corpo)) return corpo
  if (corpo === null || corpo === undefined || corpo === '') return []
  if (typeof corpo === 'object' && Array.isArray(corpo.data)) return corpo.data
  throw new Error('Resposta inesperada da Zig (esperado uma lista)')
}

function novoResumoZig() {
  const por = {}
  for (const e of ENDPOINTS_ZIG) por[e.chave] = { chamadas: 0, lidos: 0, gravados: 0, ignorados: 0, removidos: 0, falhas: 0 }
  return { lojas: 0, dias: 0, por_endpoint: por, falhas: [], tentativas_max: 1 }
}

/** Soma o retorno de uma ingestão (`{lidos, gravados, ignorados, removidos}`) no resumo. */
function acumularResumo(resumo, endpoint, retorno) {
  const r = resumo.por_endpoint[endpoint]
  r.chamadas += 1
  r.lidos += Number(retorno && retorno.lidos) || 0
  r.gravados += Number(retorno && retorno.gravados) || 0
  r.ignorados += Number(retorno && retorno.ignorados) || 0
  r.removidos += Number(retorno && retorno.removidos) || 0
  return resumo
}

function registrarFalha(resumo, falha) {
  resumo.por_endpoint[falha.endpoint].chamadas += 1
  resumo.por_endpoint[falha.endpoint].falhas += 1
  if (resumo.falhas.length < 20) resumo.falhas.push(falha)
  else resumo.falhas_omitidas = (resumo.falhas_omitidas || 0) + 1
  return resumo
}

/** Resultado final: `sucesso` sem falhas; `parcial` se parte falhou; `erro` se tudo falhou. Totais somados de todos os endpoints. */
function resumoFinalZig(resumo) {
  const tot = { lidos: 0, gravados: 0, ignorados: 0, chamadas: 0, falhas: 0 }
  for (const r of Object.values(resumo.por_endpoint)) {
    tot.lidos += r.lidos
    tot.gravados += r.gravados
    tot.ignorados += r.ignorados
    tot.chamadas += r.chamadas
    tot.falhas += r.falhas
  }
  const status = tot.falhas === 0 ? 'sucesso' : tot.falhas < tot.chamadas ? 'parcial' : 'erro'
  const erro = tot.falhas === 0 ? null
    : `${tot.falhas} de ${tot.chamadas} chamadas falharam. ` + resumo.falhas.slice(0, 3).map((f) => `${f.endpoint} ${f.loja} ${f.dia}: ${f.erro}`).join(' | ')
  const detalhes = { lojas: resumo.lojas, dias: resumo.dias, por_endpoint: resumo.por_endpoint }
  if (resumo.periodo) detalhes.periodo = resumo.periodo
  if (resumo.falhas.length) detalhes.falhas = resumo.falhas
  if (resumo.falhas_omitidas) detalhes.falhas_omitidas = resumo.falhas_omitidas
  if (resumo.aviso) detalhes.aviso = resumo.aviso
  return { status, lidos: tot.lidos, gravados: tot.gravados, ignorados: tot.ignorados, erro: erro ? erro.slice(0, 1000) : null, detalhes, tentativas: resumo.tentativas_max }
}

/**
 * Importa a Zig de uma integração (§12.5). Não abre/fecha `sync_execucoes` (quem chama faz isso).
 * deps: {
 *   requisitar(req, opcoes) → Promise<{status, corpo, tentativas}>   (lança com `.tentativas` ao esgotar)
 *   rpc(nome, args) → Promise<corpo>
 *   dormir(ms), baseUrl, pausaMs = 300, tentativas = 3, esperaMs = 10000, timeoutMs = 60000
 * }
 * Retorna `{status, lidos, gravados, ignorados, erro, detalhes, tentativas}` (formato de `ingestao_sync_finalizar`).
 * Falha ao listar/gravar lojas → lança (a execução inteira é `erro`). Falha num (loja, dia, endpoint) → segue e vira `parcial`.
 */
async function importarZig(config, entrada, deps) {
  if (!config || config.tipo !== 'zig') throw new Error('Tipo de integração incompatível')
  const token = config.segredos && config.segredos.token
  if (!token) throw new Error('Token da Zig não configurado (Integrações → Zig → segredos)')
  const rede = config.parametros && config.parametros.rede
  if (!rede) throw new Error('Parâmetro "rede" da Zig não configurado')
  const base = deps.baseUrl || ZIG_BASE_PADRAO
  const opcoesHttp = { tentativas: deps.tentativas ?? 3, esperaMs: deps.esperaMs ?? 10000, dormir: deps.dormir }
  const pausa = deps.pausaMs ?? ZIG_PAUSA_MS
  const dormir = deps.dormir || ((ms) => new Promise((ok) => setTimeout(ok, ms)))
  const periodo = periodoZig(entrada, config)
  const resumo = novoResumoZig()
  resumo.periodo = { inicio: periodo.inicio, fim: periodo.fim, truncado: periodo.truncado }

  const rLojas = await deps.requisitar(requisicaoZig(base, token, '/erp/lojas', { rede }, deps.timeoutMs), { ...opcoesHttp, rotulo: 'Zig /erp/lojas' })
  resumo.tentativas_max = Math.max(resumo.tentativas_max, rLojas.tentativas || 1)
  const lojasApi = itensDaResposta(rLojas.corpo)
  await deps.rpc('ingestao_zig_lojas', { p_integracao: config.integracao_id, p_lojas: lojasApi })
  const lojas = lojasParaSincronizar(lojasApi, config.lojas)
  resumo.lojas = lojas.length
  resumo.dias = periodo.dias.length
  if (!lojas.length) {
    resumo.aviso = lojasApi.length ? 'Nenhuma loja marcada para sincronizar' : `A Zig não devolveu lojas para a rede ${rede}`
    return resumoFinalZig(resumo)
  }

  let primeira = true
  for (const c of planejarChamadas(lojas, periodo.dias)) {
    if (!primeira && pausa > 0) await dormir(pausa)
    primeira = false
    let etapa = 'zig'
    try {
      const r = await deps.requisitar(requisicaoZig(base, token, c.caminho, paramsDia(c.loja, c.dia), deps.timeoutMs), { ...opcoesHttp, rotulo: `Zig ${c.caminho}` })
      resumo.tentativas_max = Math.max(resumo.tentativas_max, r.tentativas || 1)
      const itens = itensDaResposta(r.corpo)
      etapa = 'supabase'
      const retorno = await deps.rpc(c.rpc, { p_integracao: config.integracao_id, p_loja: c.loja, p_data: c.dia, p_itens: itens })
      acumularResumo(resumo, c.endpoint, retorno)
    } catch (e) {
      if (e && e.tentativas) resumo.tentativas_max = Math.max(resumo.tentativas_max, e.tentativas)
      registrarFalha(resumo, { loja: c.loja, dia: c.dia, endpoint: c.endpoint, etapa, status: e && e.status ? e.status : null, erro: String((e && e.message) || e).slice(0, 300) })
    }
  }
  return resumoFinalZig(resumo)
}

/**
 * Lê um endpoint paginado da Zig (`/erp/invoice`, `/erp/checkins`) juntando todas as páginas.
 * Aceita resposta `{data, page, totalPages|hasNextPage}` ou lista simples (para quando vier vazia ou menor que `pageSize`).
 */
async function lerPaginadoZig(requisitar, base, token, caminho, params, opcoes) {
  const pageSize = opcoes?.pageSize ?? 100
  const maxPaginas = opcoes?.maxPaginas ?? 200
  const todos = []
  for (let page = 1; page <= maxPaginas; page++) {
    const r = await requisitar(requisicaoZig(base, token, caminho, { ...params, page, pageSize }, opcoes?.timeoutMs), opcoes?.http)
    const corpo = r.corpo
    const itens = itensDaResposta(corpo)
    todos.push(...itens)
    if (Array.isArray(corpo)) {
      if (itens.length < pageSize) return todos
      continue
    }
    const total = Number(corpo.totalPages || corpo.lastPage || 0)
    const temMais = corpo.hasNextPage === true || (total > 0 && page < total)
    if (!temMais || !itens.length) return todos
  }
  throw new Error(`Paginação de ${caminho} passou de ${maxPaginas} páginas`)
}

// ---------------------------------------------------------------- uso neste nó
const fontes = [() => $env, () => $vars]
const cfg = configSupabase(fontes)
const http = criarHttpN8n(this.helpers)
const execucaoN8n = $execution.id

const entrada = $input.first().json
if (!entrada.integracao_id) throw new Error('Entrada sem integracao_id')

let config = null
let periodo = null
let falhaPrevia = null
try {
  config = await chamarRpc(http, cfg, 'ingestao_integracao_config', { p_integracao: entrada.integracao_id })
  periodo = periodoZig(entrada, config)
} catch (e) {
  falhaPrevia = e
}

const saida = await comExecucao(http, cfg, {
  tipo: 'zig_importar',
  gatilho: entrada.gatilho,
  workflow: NOMES_WORKFLOWS.ZIG_IMPORTAR,
  empresa_id: entrada.empresa_id || (config && config.empresa_id) || null,
  integracao_id: entrada.integracao_id,
  solicitacao_id: entrada.solicitacao_id || null,
  periodo_inicio: periodo ? periodo.inicio : entrada.data_inicio || null,
  periodo_fim: periodo ? periodo.fim : entrada.data_fim || null,
  n8n_execution_id: execucaoN8n,
}, async () => {
  if (falhaPrevia) throw falhaPrevia
  return importarZig(config, entrada, {
    baseUrl: lerVariavel('ZIG_BASE_URL', fontes, ZIG_BASE_PADRAO),
    requisitar: (req, opcoes) => requisitarComRetentativa(http, req, opcoes),
    rpc: (nome, args) => chamarRpc(http, cfg, nome, args),
  })
})

// Saída do subfluxo (contrato §12.3)
return [{ json: { execucao_ids: saida.execucao_ids, status: saida.status, lidos: saida.lidos, gravados: saida.gravados, ignorados: saida.ignorados, erro: saida.erro } }]
